const e={id:"atomic-habits",title:"Atomic Habits",author:"James Clear",courseIds:["turning-day","identity"],sources:[{id:"atomic-identification",title:"Atomic Habits author description",url:"https://jamesclear.com/atomic-habits",citation:"Clear, J. Atomic Habits. Official author book page, accessed 2026-10-08.",kind:"book-identification",population:"Author/developer description, no empirical sample.",finding:"Identifies the book and themes only.",limitation:"Promotional practitioner material; not evidence for efficacy.",checkedOn:"2026-10-08"},{id:"atomic-identity-identification",title:"Identity as a habit framing",url:"https://jamesclear.com/identity-votes",citation:"Clear, J. How to change your beliefs and stick to your goals for good. Official author excerpt, accessed 2026-10-08; consulted for theme identification only.",kind:"book-identification",population:"Author/developer description, no empirical sample.",finding:"Identifies the book and themes only.",limitation:"Promotional practitioner material; not evidence for efficacy.",checkedOn:"2026-10-08"},{id:"habit-context",title:"Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",citation:"Wood, W., & Rünger, D. (2016). Psychology of habit. Annual Review of Psychology, 67, 289–314. DOI: 10.1146/annurev-psych-122414-033417.",kind:"review",population:"Human habit research across laboratory and everyday settings; narrative review, no pooled sample.",finding:"Repeated actions in recurring contexts can become cued by those contexts.",limitation:"No isolated test of object placement, a branded recipe, identity-first superiority, or instant celebration-driven habit formation.",checkedOn:"2026-10-08",dossier:"turning-day.md T08; identity.md I06; motivation.md M07"},{id:"habit-time",title:"Time to form a habit",url:"https://www.newswise.com/pdf_docs/173752351874824_healthcare-12-02488.pdf",citation:"Singh, B., Murphy, A., Maher, C., & Smith, A. E. (2024). Time to form a habit: A systematic review and meta-analysis of health behaviour habit formation and its determinants. Healthcare, 12(23), 2488. DOI: 10.3390/healthcare12232488.",kind:"meta-analysis",population:"20 health-behavior studies, 2,601 participants; 11 studies at high risk of bias.",finding:"Formation time differed substantially; only four studies provided timing estimates.",limitation:"No universal deadline; pre-post habit-strength estimate is not a controlled treatment effect.",checkedOn:"2026-10-08",dossier:"turning-day.md T07; identity.md I05; VERIFY.md denominator and access corrections"},{id:"activity-identity",title:"Intervention effects on physical activity identity",url:"https://pubmed.ncbi.nlm.nih.gov/40008714/",citation:"Rhodes, R. E., Wierts, C. M., Kullman, S., Magel, E., & Strachan, S. (2025). Intervention effects on physical activity identity: A systematic review and meta-analysis. Health Psychology Review, 19(1), 123–144. DOI: 10.1080/17437199.2024.2412996.",kind:"meta-analysis",population:"Adults over 18; 40 identity effects, 4,939 participants; 30 effects also measured physical activity.",finding:"Interventions produced a small identity effect, g = 0.18, 95% CI 0.11–0.24.",limitation:"Physical-activity programs do not establish that identity must change before behavior or validate a general identity-first habit method; heterogeneity and bias remain.",checkedOn:"2026-10-08",dossier:"identity.md I19; VERIFY.md adult eligibility correction"},{id:"progress-monitoring",title:"Does monitoring goal progress promote goal attainment?",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",citation:"Harkin, B., Webb, T. L., Chang, B. P. I., Prestwich, A., Conner, M., Kellar, I., Benn, Y., & Sheeran, P. (2016). Does monitoring goal progress promote goal attainment? A meta-analysis of the experimental evidence. Psychological Bulletin, 142(2), 198–229. DOI: 10.1037/bul0000025.",kind:"meta-analysis",population:"138 randomized studies, 19,951 participants with varied goals.",finding:"Goal attainment improved on average, d = 0.40, 95% CI 0.32–0.48 in opened abstract.",limitation:"Protocols varied; recording/reporting moderators do not validate a particular tracker, streak rule or review schedule.",checkedOn:"2026-10-08",dossier:"turning-day.md T05; focus.md F03; procrastination.md P13"},{id:"if-then-plans",title:"Implementation intentions and goal achievement",url:"https://www.researchgate.net/profile/Peter-Gollwitzer-2/publication/37367696_Implementation_Intentions_and_Goal_Achievement_A_Meta-Analysis_of_Effects_and_Processes/links/59d91a24a6fdcc2aad0d8c1f/Implementation-Intentions-and-Goal-Achievement-A-Meta-Analysis-of-Effects-and-Processes.pdf",citation:"Gollwitzer, P. M., & Sheeran, P. (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology, 38, 69–119. DOI: 10.1016/S0065-2601(06)38002-1.",kind:"meta-analysis",population:"94 tests, 8,461 participants; diverse laboratory and field goals, predominantly student samples.",finding:"Specific cue-response plans improved goal attainment on average, d = 0.65, 95% CI 0.60–0.70.",limitation:"Older synthesis includes 83 experimental and 11 correlational tests; not proof of GTD, time blocking, an ODA action, or a two-minute dose.",checkedOn:"2026-10-08",dossier:"turning-day.md T03; focus.md F04; procrastination.md P03; VERIFY.md design correction"}],locales:{en:{hook:"Another fresh start that lasted three days? Make the next attempt easier to repeat.",intro:"A new routine can look convincing on Sunday and become awkward by Wednesday. Clear asks readers to pay attention to the conditions around repeated behavior, the size of the first step, and the stories they tell about themselves. ODA checks those themes separately because useful advice and a tested mechanism are different things. You can borrow a practical experiment without accepting every broad promise attached to it. The aim here is one repeatable action in your actual day, with an honest record of what happened and permission to revise the setup when life changes.",ideas:[{id:"repeatable-context",title:"Give the action a dependable place in your day",idea:"Clear treats the surroundings of a behavior as part of the work of changing it, rather than leaving every repetition to a fresh burst of determination. Choose a situation you already encounter and make the intended response easy to find there, without assuming that a perfectly arranged room will solve an unreasonable workload. An ODA adaptation is to leave the document you need open before a planned writing session and decide what you will do when you arrive. Test whether that arrangement fits the day you actually have, including travel, care responsibilities and accessible tools.",research:"Research supports repeated behavior in recurring contexts as a route toward cue-driven habits: Wood and Rünger review several converging lines of human research. A 2024 review of 20 health-behavior studies also found wide variation in habit development, with only four studies reporting formation times. There is no dependable deadline after which your action must feel automatic, and these papers do not test your particular desk arrangement. Use the cue to create another feasible opportunity, then judge repetition over time instead of interpreting a difficult morning as proof that you cannot change.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Make the entry step small enough to attempt",idea:"The book recommends reducing the initial demand of a routine so that beginning is a concrete choice instead of a negotiation about an entire project. A small entry can be opening the relevant file and writing the question you need to answer; it should connect to the work you value rather than become a permanent substitute for it. Keep the first step modest on a busy day, and decide separately whether more work is possible. This is a design option, so there is no obligation to keep going just because you started or to count preparation as completed output.",research:"The strongest nearby evidence concerns specific plans and repeated context, rather than a universal tiny-action dose. Gollwitzer and Sheeran found an average benefit for cue-response plans across 94 tests, but the older synthesis mixed settings and study designs. That does not establish two minutes as an optimal threshold, show that every smaller action creates motivation, or validate the full method in this book. Treat the brief start as your own low-cost experiment: record whether you attempted it, whether useful work followed, and what adjustment you need before the next opportunity.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Let your description of yourself remain editable",idea:"Clear connects repeated choices with a reader’s sense of who they are, proposing that a new personal description can support a desired routine. You can use that idea gently by describing the behavior you are practicing, instead of declaring a complete personality change before you have tested the routine. If you miss a chance, revise the plan rather than turning the miss into evidence of an inferior identity. A useful description makes the next choice more approachable; it should not ask you to deny uncertainty, disability, competing commitments or the need for help.",research:"A 2025 meta-analysis found small improvements in physical-activity identity following interventions, but those programs combined varied ingredients and concerned adults’ exercise behavior. The evidence does not establish that identity must change first or that saying a new identity causes a routine to last. Habit research also describes behavior and deliberate goals interacting, rather than a single direction of influence. The verdict is mixed for this broad framing: it may help you organize an intention, while the concrete attempt still provides clearer information than a confident statement about the person you have become.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Use a record to learn, not to protect a streak",idea:"Tracking in the book makes repeated behavior visible, but a mark on a calendar should answer a useful question about your plan. Record the opportunity, the attempt and the relevant result separately when they differ, so that an unopened file and a finished paragraph do not become the same event. After a missed opportunity, ask whether the cue was absent, the action was too large or another obligation took priority. Choose the next feasible attempt and allow safe pauses, rather than inventing a punishment to defend the appearance of consistency.",research:"Harkin and colleagues reviewed 138 randomized studies and found that progress-monitoring interventions improved goal attainment on average. Larger effects accompanied physically recording or reporting progress, but those comparisons do not prove that public sharing is necessary or that every tracker format works. The review does not validate a particular streak threshold, and variable habit-formation evidence does not provide one either. A private, accurate note is a reasonable adaptation; its value is the decision it helps you revise, not an implication that a long chain proves your health, character or eventual success.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"Prepare one repeatable start in two minutes",steps:["Choose one ordinary cue you expect today and one useful action that fits within a minute.","Write the cue and action together, then put the needed material where you will use it.","Keep the plan visible for that opportunity and leave a place to record what actually happens."],decision:"Today I will write one cue and one small useful action, then prepare the material for the attempt."},takeaway:"Keep the repeatable context and the honest record. Hold identity language and the exact size of the start more lightly, because their strongest versions are not settled by the evidence checked here. Today’s two-minute preparation is an ODA adaptation, not a clinically tested dose or a promise of automatic behavior. You are deciding what to try at one opportunity. Tomorrow, the relevant question is whether the cue, action and circumstances fit well enough to try again."},tr:{hook:"Yine üç gün süren bir başlangıç mı? Bir sonraki denemeyi tekrarlamak daha kolay olsun.",intro:"Pazar günü kusursuz görünen bir düzen, çarşamba günü hayatına sığmayabilir. Clear, aynı davranışı çevreleyen koşullara, başlangıç adımının büyüklüğüne ve kendini nasıl tanımladığına bakmanı öneriyor. ODA bu fikirleri ayrı ayrı inceliyor; işe yarayabilecek bir öneri ile araştırmada sınanmış bir mekanizma aynı şey değil. Kitaptaki bütün büyük vaatleri kabul etmeden de kullanışlı bir deneme yapabilirsin. Buradaki amaç, gerçekten yaşadığın günün içinde tekrarlanabilir tek bir eylem seçmek. Ne olduğunu dürüstçe kaydet, koşullar değişince düzeni de değiştirebil. Başlamak için yeni bir kimliğe ya da kusursuz bir sabaha ihtiyacın olduğunu varsayma.",ideas:[{id:"repeatable-context",title:"Eyleme gününde güvenilir bir yer aç",idea:"Clear, bir davranışın çevresini değişim işinin parçası sayıyor; her tekrarı yeniden heveslenmene bırakmanı istemiyor. Zaten karşılaştığın bir durum seç ve yapmak istediğin şeyi o anda kolayca bulabileceğin bir yere koy, ama çok iyi düzenlenmiş bir masanın aşırı iş yükünü çözmesini bekleme. ODA uyarlaması olarak, ayırdığın yazı zamanından önce gerekli dosyayı açık bırakabilir ve masaya geldiğinde hangi soruyla başlayacağını belirleyebilirsin. Bu düzenin yolculuk, bakım sorumlulukları ve erişilebilirlik ihtiyaçlarınla birlikte gerçek gününe uyup uymadığını dene; özellikle her gün aynı saate sahip olacağını baştan kabul etme.",research:"Wood ve Rünger’in derlemesi, aynı bağlamda tekrarlanan davranışların zamanla o bağlamın işaretleriyle tetiklenebildiğini gösteren farklı araştırmaları bir araya getiriyor. Sağlık davranışlarını inceleyen 2024 tarihli derleme de alışkanlık gelişiminde geniş farklılıklar buldu; 20 çalışmanın yalnızca dördü oluşma süresine ilişkin tahmin sundu. Davranışının belli bir tarihte mutlaka otomatikleşmesi gerektiğini söyleyen güvenilir bir son tarih yok. Bu çalışmalar senin masa düzenini özel olarak sınamıyor ve her karmaşık hedefin bütünüyle otomatikleşeceğini de göstermiyor. İşareti yeni bir uygun fırsat yaratmak için kullan; zor bir sabahı değişemeyeceğinin kanıtı saymak yerine, zaman içindeki gerçek tekrarları değerlendir ve koşulların nasıl değiştiğini kaydet.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Başlangıcı gerçekten deneyebileceğin kadar küçült",idea:"Kitap, bir düzenin ilk talebini azaltmayı öneriyor; böylece başlamak, bütün projeyi bitirip bitiremeyeceğin üzerine bir pazarlığa dönüşmüyor. Küçük giriş adımı, ilgili dosyayı açıp cevaplaman gereken soruyu yazmak olabilir, ama değer verdiğin işle bağlantısını korusun ve sürekli onun yerine geçmesin. Yoğun bir günde ilk adımı küçük tutabilir, devam edecek zamanın ve gücün olup olmadığını ayrı bir karar olarak ele alabilirsin. Başladın diye mutlaka sürdürmek zorunda değilsin; dosyayı hazırlamak ile işe yarar bir paragraf üretmek farklı sonuçlar, ikisini kayıtta da birbirine karıştırma.",research:"Yakındaki en güçlü bulgular, evrensel bir küçük eylem süresinden çok belirli planlar ve tekrarlanan bağlamla ilgili. Gollwitzer ve Sheeran, 94 farklı sınamada durumu bir davranışa bağlayan planların hedefe ulaşmaya ortalama katkısını buldu; eski derleme farklı ortamları ve çalışma tasarımlarını içeriyor. Bu sonuç, iki dakikanın en iyi eşik olduğunu, her küçük adımın motivasyon yarattığını ya da kitaptaki bütün yöntemin doğrulandığını göstermiyor. Kısa başlangıcı düşük maliyetli kişisel bir deneme olarak gör. Deneyip denemediğini, ardından işe yarar çalışma gelip gelmediğini ve bir sonraki fırsattan önce neyi değiştireceğini ayrı ayrı yaz; sonuç çıkmadığında süreyi sihirli bir kural gibi savunman gerekmiyor.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Kendini tanımlama biçimin değişebilir kalsın",idea:"Clear, tekrarlanan seçimlerle kişinin kendini nasıl gördüğü arasında bağlantı kuruyor ve yeni bir tanımın istediğin düzeni destekleyebileceğini öne sürüyor. Bu fikri, henüz denemediğin bir rutinden önce bütün kişiliğinin değiştiğini ilan etmek yerine, çalıştığın davranışı tarif ederek kullanabilirsin. Bir fırsatı kaçırdığında, bunu değersiz ya da yetersiz biri olduğunun deliline çevirmek yerine planını gözden geçir. Seçtiğin tanım bir sonraki adımı daha ulaşılabilir kılsın; belirsizliğini, engelliliğini, başka sorumluluklarını ya da destek ihtiyacını yok saymanı istemesin, çünkü tek bir davranış hayatının tamamını açıklamaz.",research:"2025 tarihli bir meta-analiz, fiziksel etkinlik müdahalelerinden sonra yetişkinlerin bu etkinlikle ilgili kimlik algısında küçük iyileşmeler buldu. Fakat programlar farklı bileşenler içeriyordu ve yetişkinlerin hareket davranışıyla ilgiliydi; sonuçlar önce kimliğin değişmesi gerektiğini ya da yeni bir tanımı söylemenin rutini kalıcı hale getirdiğini kanıtlamıyor. Alışkanlık araştırmaları da davranış ile bilinçli hedeflerin etkileşimini anlatıyor, tek yönlü bir neden zincirini değil. Bu geniş çerçeve için sonuç karışık. Niyetini düzenlemene yardımcı olabilir, ama kendine verdiğin iddialı bir unvandan çok yaptığın somut deneme bilgi sağlar. Tanım sana baskı yaptığında onu sadeleştir; hangi davranışı hangi koşulda denediğin daha açık bir kayıt sunar.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Kaydı seri korumak için değil, öğrenmek için tut",idea:"Kitapta takip, tekrarlanan davranışı görünür kılıyor; fakat takvimdeki işaret, planın hakkında işe yarar bir soruya cevap vermeli. Fırsat, deneme ve sonuç birbirinden farklıysa onları ayrı kaydet; açılmamış bir dosya ile tamamlanan paragraf aynı olay olmasın. Kaçırdığın fırsattan sonra işaretin ortaya çıkıp çıkmadığına, eylemin fazla büyük olup olmadığına veya başka bir sorumluluğun öne geçip geçmediğine bak. Görünürdeki sürekliliği korumak için ceza uydurmak yerine bir sonraki uygun denemeyi seç ve güvenli ara vermeye izin ver; özel koşullarını başkalarına açıklaman da şart değil.",research:"Harkin ve çalışma arkadaşları, 138 rastgele atamalı çalışmayı inceleyerek ilerlemeyi izlemeye yönelik müdahalelerin hedefe ulaşmayı ortalama olarak iyileştirdiğini buldu. İlerlemenin fiziksel olarak kaydedildiği ya da paylaşıldığı çalışmalarda etkiler daha büyüktü, ama bu karşılaştırmalar paylaşmanın şart olduğunu veya her takip biçiminin işe yaradığını kanıtlamıyor. Derleme belirli bir seri kuralını doğrulamıyor; alışkanlık süresi bulguları da böyle bir eşik vermiyor. Özel ve doğru bir not, makul bir uyarlama. Değeri, planını nasıl değiştireceğine yardımcı olmasında; uzun bir işaret zincirinin sağlığını, karakterini ya da gelecekteki başarını kanıtladığını ima etmesinde değil. Planlanan çalışma ile gerçekleşen çalışmayı aynı haneye yazma.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"İki dakikada tekrarlanabilir bir başlangıç hazırla",steps:["Bugün karşılaşacağın sıradan bir işaret ve bir dakikaya sığan işe yarar bir eylem seç.","İşaretle eylemi aynı cümlede yaz, gerekli malzemeyi kullanacağın yere koy.","Planı o fırsat için görünür tut, gerçekte ne olduğunu daha sonra yazacağın yeri ayır."],decision:"Bugün bir işaret ve küçük, işe yarar bir eylem yazıp deneme için gerekli malzemeyi hazırlayacağım."},takeaway:"Tekrarlanabilir bağlamı ve dürüst kaydı koru. Kimlik dilini ve başlangıcın tam büyüklüğünü daha esnek tut; bunların güçlü vaatleri burada incelenen kanıtlarla kesinleşmiş değil. İki dakikalık hazırlık, ODA’nın uyarlaması; klinik olarak sınanmış bir süre veya otomatik davranış garantisi değil. Şu an tek bir fırsatta ne deneyeceğini seçiyorsun. Yarın bakacağın şey, işaretin, eylemin ve koşulların tekrar denemeye yeterince uyup uymadığı. İyi görünen bir plana bağlı kalmak uğruna gerçek ihtiyaçlarını dışarıda bırakma; değişiklik yapman, denemeden öğrendiğin bilgiyi kullanmandır."},es:{hook:"¿Otro comienzo que duró tres días? Haz que el próximo intento encaje mejor en tu día.",intro:"Una rutina que parece perfecta el domingo puede resultar impracticable el miércoles. Clear propone mirar las condiciones que rodean la conducta, el tamaño del primer paso y la manera de describirte. ODA comprueba cada idea por separado: un consejo útil y un mecanismo probado no son lo mismo. Puedes tomar una propuesta concreta sin aceptar todas sus promesas. Aquí buscamos una acción que puedas repetir en tu vida real, un registro sincero de lo ocurrido y libertad para cambiar el plan cuando cambien las circunstancias. No necesitas declarar que eres otra persona antes de probarlo.",ideas:[{id:"repeatable-context",title:"Busca un contexto que vuelva a aparecer",idea:"Clear considera que el entorno forma parte del trabajo de cambiar una conducta, en lugar de dejar cada repetición a un nuevo arranque de entusiasmo. Elige una situación habitual y deja a mano lo necesario, sin esperar que una mesa bien preparada resuelva una carga de trabajo excesiva. Una adaptación de ODA consiste en dejar abierto el documento para una sesión prevista y decidir qué harás al sentarte. Comprueba si ese arreglo encaja con tus desplazamientos, responsabilidades de cuidado y herramientas de accesibilidad; el horario ideal sobre el papel puede no estar disponible en tu día.",research:"La revisión de Wood y Rünger reúne varias líneas de investigación que apoyan la repetición en contextos recurrentes como vía hacia conductas activadas por señales. Una revisión de 2024, con 20 estudios de hábitos de salud, encontró grandes diferencias en su desarrollo; solo cuatro aportaron estimaciones del tiempo de formación. No hay una fecha fiable a partir de la cual tu acción deba resultar automática, ni se ha probado aquí tu disposición particular de la mesa. Utiliza la señal para crear otra oportunidad viable. Evalúa las repeticiones a lo largo del tiempo, en vez de convertir una mañana difícil en una conclusión sobre tu capacidad para cambiar.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Haz pequeño el acceso, sin perder de vista el trabajo",idea:"El libro recomienda reducir la exigencia inicial para que empezar sea una decisión concreta y no una negociación sobre todo el proyecto. Abrir el archivo y escribir la pregunta que necesitas resolver puede ser un inicio útil, siempre que mantenga su relación con el trabajo y no lo sustituya indefinidamente. En un día ocupado, elige una entrada modesta y decide aparte si puedes continuar. Empezar no te obliga a seguir, y preparar el material no equivale a producir un resultado; conviene distinguir ambos hechos cuando revises lo ocurrido.",research:"La evidencia más sólida cercana a esta propuesta se refiere a planes específicos y contextos repetidos, no a una dosis universal de acciones diminutas. Gollwitzer y Sheeran observaron beneficios medios de los planes que conectan una señal con una respuesta en 94 pruebas, con distintos entornos y diseños. Eso no demuestra que dos minutos sean el umbral óptimo, que toda acción pequeña genere motivación ni que el método completo del libro esté validado. Toma el inicio breve como un experimento de bajo coste. Anota si lo intentaste, si después hubo trabajo útil y qué cambiarías antes de la siguiente oportunidad.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Deja margen para cambiar cómo te describes",idea:"Clear relaciona las elecciones repetidas con la idea que tienes de quién eres y propone que una nueva descripción personal apoye la rutina deseada. Puedes emplear ese enfoque con cuidado, describiendo la conducta que estás practicando en lugar de anunciar un cambio completo de personalidad. Si pierdes una oportunidad, revisa el plan en vez de convertirla en prueba de una identidad inferior. Una descripción útil hace más accesible la siguiente elección; no te exige negar incertidumbres, discapacidad, compromisos que compiten o necesidad de apoyo.",research:"Un metaanálisis de 2025 encontró pequeñas mejoras en la identidad relacionada con la actividad física tras distintas intervenciones. Sin embargo, los programas combinaban ingredientes y trataban el ejercicio de personas adultas: no establecen que la identidad tenga que cambiar primero ni que enunciar una identidad mantenga una rutina. La investigación sobre hábitos también describe interacciones entre conducta y objetivos deliberados, no una única dirección causal. El resultado es mixto para este marco amplio. Puede servir para ordenar una intención, pero el intento concreto aporta información más clara que una afirmación convincente sobre la persona en la que te has convertido.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Registra para aprender, no para defender una racha",idea:"En el libro, el seguimiento hace visible la repetición, pero una marca en el calendario debe responder una pregunta útil sobre tu plan. Separa la oportunidad, el intento y el resultado cuando no coincidan, para que un archivo sin abrir no cuente igual que un párrafo terminado. Si no lo hiciste, comprueba si faltó la señal, si la acción era demasiado grande o si otra obligación tuvo prioridad. Elige la siguiente oportunidad viable y permite pausas seguras, en lugar de inventar castigos para proteger la apariencia de constancia.",research:"Harkin y sus colegas revisaron 138 estudios aleatorizados y encontraron que las intervenciones de seguimiento mejoraban, por término medio, el logro de objetivos. Los efectos eran mayores cuando el progreso se registraba físicamente o se comunicaba, pero esas comparaciones no prueban que compartirlo sea obligatorio ni que cualquier formato funcione. La revisión no valida un número de fallos que rompa necesariamente una rutina; la variabilidad del tiempo de formación tampoco lo aporta. Un registro privado y preciso es una adaptación razonable. Su valor está en la decisión que ayuda a revisar, no en presentar una cadena de marcas como prueba de salud, carácter o éxito futuro.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"Prepara un inicio repetible en dos minutos",steps:["Elige una señal cotidiana que esperes hoy y una acción útil que quepa en un minuto.","Escribe juntas la señal y la acción; coloca el material donde lo usarás.","Deja el plan visible para esa oportunidad y reserva un lugar para registrar lo ocurrido."],decision:"Hoy escribiré una señal y una acción pequeña, y dejaré preparado el material para intentarla."},takeaway:"Conserva el contexto repetible y el registro honesto. Usa con más flexibilidad el lenguaje de identidad y el tamaño exacto del inicio, porque sus versiones más fuertes no quedan resueltas por la evidencia revisada. Esta preparación de dos minutos es una adaptación de ODA, no una dosis clínica ni una promesa de automatismo. Decides qué probar en una oportunidad. Después podrás comprobar si la señal, la acción y las circunstancias encajan lo suficiente para repetir, sin defender un plan que ha dejado de corresponder con tu vida."},fr:{hook:"Encore un nouveau départ qui tient trois jours ? Facilite la prochaine répétition.",intro:"Une routine convaincante le dimanche peut devenir impraticable dès mercredi. Clear invite à regarder les conditions qui entourent le comportement, la taille du premier pas et la façon dont tu te décris. ODA examine chaque idée séparément, car un conseil utile ne constitue pas une preuve de son mécanisme. Tu peux essayer une proposition sans reprendre toutes ses promesses. Ici, le but est une action répétable dans ta vraie journée, un relevé honnête de ce qui se passe et la possibilité de modifier le dispositif. Tu n’as pas à annoncer une nouvelle personnalité avant de vérifier si le geste te convient.",ideas:[{id:"repeatable-context",title:"Donne au geste un contexte qui revient",idea:"Clear considère l’environnement comme une partie du travail de changement, plutôt que de confier chaque répétition à un nouvel élan de volonté. Choisis une situation habituelle et rends le matériel disponible à ce moment, sans demander à un bureau bien rangé de résoudre une charge excessive. Une adaptation ODA consiste à laisser ouvert le document d’une séance d’écriture prévue et à décider du premier geste en arrivant. Vérifie que ce dispositif convient aussi aux déplacements, aux responsabilités de soin et aux outils d’accessibilité; un rendez-vous idéal sur le papier ne garantit pas une occasion réelle.",research:"La revue de Wood et Rünger rassemble plusieurs travaux qui soutiennent la répétition dans des contextes récurrents comme voie vers des comportements déclenchés par des indices. Une revue de 2024 portant sur 20 études d’habitudes de santé a également constaté une grande variabilité; quatre études seulement donnaient des estimations du temps de formation. Aucune échéance fiable ne permet d’exiger que ton geste soit devenu automatique à une date précise. Ces travaux ne testent pas non plus ton bureau particulier. Utilise le repère pour créer une occasion faisable, puis regarde les répétitions dans la durée, sans transformer une matinée difficile en verdict sur ta capacité à changer.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Réduis le premier pas, tout en gardant sa fonction",idea:"Le livre conseille de réduire la demande initiale pour que commencer soit une décision concrète, plutôt qu’une négociation sur l’ensemble du projet. Ouvrir le fichier et écrire la question à résoudre peut constituer une entrée utile, à condition de rester lié au travail et de ne pas le remplacer indéfiniment. Dans une journée chargée, garde un début modeste et décide séparément si tu peux poursuivre. Avoir commencé ne t’oblige pas à continuer, et préparer le matériel ne signifie pas avoir produit le résultat; distingue les deux quand tu fais le point.",research:"Les données les plus solides à proximité concernent les plans précis et les contextes répétés, plutôt qu’une dose universelle de petits gestes. Gollwitzer et Sheeran ont trouvé un bénéfice moyen des plans reliant une situation à une réponse dans 94 tests, avec des cadres et des méthodes variés. Cela ne prouve pas que deux minutes soient un seuil optimal, que tout petit geste crée de la motivation ou que la méthode entière du livre soit validée. Considère ce début comme un essai peu coûteux. Note si tu l’as tenté, si un travail utile a suivi et ce qu’il faudrait changer avant la prochaine occasion.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Garde une description de toi que tu peux réviser",idea:"Clear relie les choix répétés à la manière de se percevoir et propose qu’une nouvelle description personnelle soutienne la routine souhaitée. Tu peux utiliser cette idée avec souplesse, en décrivant le comportement que tu pratiques plutôt qu’un changement complet de personnalité encore non testé. Si tu rates une occasion, revois le plan sans en faire une preuve d’une identité inférieure. Une description utile rend le prochain choix plus accessible; elle ne te demande pas de nier une incertitude, un handicap, des responsabilités concurrentes ou un besoin d’aide.",research:"Une méta-analyse de 2025 a trouvé de petites améliorations de l’identité liée à l’activité physique après des interventions. Mais les programmes associaient différents éléments et concernaient l’exercice chez des adultes: ils ne montrent pas que l’identité doit changer d’abord ni qu’énoncer une nouvelle identité fait durer une routine. Les recherches sur les habitudes décrivent aussi des interactions entre comportements et objectifs délibérés, plutôt qu’une causalité à sens unique. Le verdict est mitigé pour ce cadre général. Il peut aider à formuler une intention, mais une tentative concrète donne une information plus nette qu’une affirmation assurée sur la personne que tu serais devenue.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Utilise le relevé pour apprendre, pas pour sauver une série",idea:"Le suivi rend la répétition visible dans le livre, mais une marque sur le calendrier devrait répondre à une question utile sur ton plan. Sépare l’occasion, la tentative et le résultat lorsqu’ils diffèrent, pour qu’un fichier non ouvert ne compte pas comme un paragraphe terminé. Après une occasion manquée, vérifie si le repère était absent, si le geste était trop ambitieux ou si une autre obligation passait avant. Choisis la prochaine tentative faisable et autorise les pauses nécessaires, plutôt que d’inventer une sanction pour préserver une apparence de régularité.",research:"Harkin et ses collègues ont examiné 138 études randomisées et trouvé un bénéfice moyen des interventions de suivi sur l’atteinte des objectifs. Les effets étaient plus grands avec un relevé matériel ou une communication des progrès, mais ces comparaisons ne prouvent ni l’obligation de partager ni l’efficacité de tous les formats. La revue ne valide aucun seuil de rupture d’une série, et les données variables de formation des habitudes n’en fournissent pas davantage. Une note privée et exacte est une adaptation raisonnable. Sa valeur est d’aider à revoir une décision, pas de faire passer une longue chaîne de marques pour une preuve de santé, de caractère ou de réussite future.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"Prépare un début répétable en deux minutes",steps:["Choisis un repère ordinaire attendu aujourd’hui et un geste utile qui tient en une minute.","Écris ensemble le repère et le geste, puis place le matériel à l’endroit prévu.","Garde ce plan visible et prévois une place pour noter ensuite ce qui s’est passé."],decision:"Aujourd’hui, j’écrirai un repère et un petit geste utile, puis je préparerai le matériel nécessaire."},takeaway:"Garde le contexte répétable et le relevé honnête. Utilise plus librement le vocabulaire de l’identité et la taille exacte du début, car leurs versions les plus fortes ne sont pas établies par les données examinées. La préparation de deux minutes est une adaptation ODA, pas une dose clinique ni une promesse d’automatisme. Tu décides quoi essayer à une occasion précise. Tu pourras ensuite vérifier si le repère, le geste et les circonstances conviennent suffisamment pour recommencer, sans défendre un dispositif qui ne correspond plus à ta vie."},de:{hook:"Wieder ein Neustart, der drei Tage hielt? Mach den nächsten Versuch leichter wiederholbar.",intro:"Eine Routine kann am Sonntag überzeugend aussehen und am Mittwoch nicht mehr in deinen Tag passen. Clear lenkt den Blick auf die Bedingungen einer Handlung, die Größe des ersten Schritts und deine Beschreibung von dir selbst. ODA prüft diese Ideen einzeln, denn ein brauchbarer Rat ist noch kein belegter Wirkmechanismus. Du kannst eine praktische Anregung ausprobieren, ohne alle großen Versprechen zu übernehmen. Hier geht es um eine Handlung in deinem tatsächlichen Alltag, eine ehrliche Notiz über den Verlauf und die Freiheit, den Aufbau zu ändern. Eine neue Persönlichkeit musst du dafür nicht vorab erklären.",ideas:[{id:"repeatable-context",title:"Gib der Handlung einen verlässlichen Platz im Tag",idea:"Clear versteht die Umgebung einer Handlung als Teil der Veränderungsarbeit, statt jede Wiederholung einem neuen Anlauf von Entschlossenheit zu überlassen. Wähle eine Situation, die ohnehin vorkommt, und lege das Benötigte dort bereit, ohne von einem gut eingerichteten Schreibtisch die Lösung für zu viel Arbeit zu erwarten. Als ODA-Anpassung kannst du vor einer geplanten Schreibzeit das passende Dokument öffnen und festlegen, womit du beim Hinsetzen beginnst. Prüfe, ob diese Anordnung zu Fahrwegen, Betreuungspflichten und Hilfsmitteln passt; ein idealer Zeitpunkt auf dem Papier ist nicht automatisch eine verfügbare Gelegenheit im Alltag.",research:"Der Überblick von Wood und Rünger bündelt verschiedene Forschungslinien dazu, wie wiederholte Handlungen in wiederkehrenden Situationen durch deren Hinweise ausgelöst werden können. Eine Übersicht von 2024 zu 20 Studien über Gesundheitsgewohnheiten fand außerdem große Unterschiede bei der Entwicklung; nur vier Studien lieferten Schätzungen zur Entstehungsdauer. Es gibt keinen verlässlichen Termin, zu dem deine Handlung automatisch werden muss, und diese Arbeiten prüfen nicht deine konkrete Schreibtischanordnung. Nutze den Hinweis für eine weitere machbare Gelegenheit. Betrachte die tatsächlichen Wiederholungen über längere Zeit, statt aus einem schwierigen Morgen auf fehlende Veränderungsfähigkeit zu schließen; auch komplexe Ziele werden dadurch nicht vollständig automatisch.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Verkleinere den Einstieg, ohne die eigentliche Arbeit zu verlieren",idea:"Das Buch empfiehlt, die erste Anforderung zu reduzieren, damit der Beginn eine konkrete Wahl bleibt und keine Verhandlung über das ganze Projekt wird. Die Datei zu öffnen und die zu klärende Frage aufzuschreiben kann ein nützlicher Einstieg sein, solange er mit der gewünschten Arbeit verbunden bleibt und sie nicht dauerhaft ersetzt. Halte den ersten Schritt an einem vollen Tag klein und entscheide getrennt, ob weitere Arbeit möglich ist. Ein Beginn verpflichtet dich nicht zum Weitermachen, und Vorbereitung ist kein fertiges Ergebnis; diese Unterscheidung gehört auch in deine spätere Notiz.",research:"Die stärkeren verwandten Befunde betreffen konkrete Pläne und wiederkehrende Situationen, nicht eine universelle Dosis winziger Handlungen. Gollwitzer und Sheeran fanden im Mittel Vorteile für Pläne, die einen Hinweis mit einer Reaktion verbinden, in 94 Tests mit unterschiedlichen Umgebungen und Studiendesigns. Das belegt weder zwei Minuten als optimale Grenze noch, dass jeder kleine Schritt Motivation erzeugt oder die gesamte Buchmethode wirksam ist. Behandle den kurzen Einstieg als günstigen eigenen Versuch. Notiere, ob du ihn versucht hast, ob brauchbare Arbeit folgte und welche Änderung die nächste Gelegenheit braucht; verteidige eine genaue Minutenzahl nicht wie ein Naturgesetz.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Halte deine Selbstbeschreibung veränderbar",idea:"Clear verbindet wiederholte Entscheidungen mit der Vorstellung, wer man ist, und schlägt eine neue Selbstbeschreibung als Hilfe für gewünschte Routinen vor. Du kannst das behutsam nutzen, indem du die Handlung beschreibst, die du übst, statt einen vollständigen Persönlichkeitswandel auszurufen. Wenn eine Gelegenheit ausfällt, überprüfe den Plan, statt daraus einen Beleg für eine minderwertige Identität zu machen. Eine brauchbare Beschreibung erleichtert die nächste Entscheidung; sie verlangt nicht, Unsicherheit, Behinderung, konkurrierende Verpflichtungen oder Unterstützungsbedarf zu leugnen, und muss nicht alle Bereiche deines Lebens erklären.",research:"Eine Metaanalyse von 2025 fand kleine Verbesserungen der bewegungsbezogenen Identität nach Interventionen bei Erwachsenen. Die Programme verbanden jedoch verschiedene Bestandteile und betrafen körperliche Aktivität; sie zeigen nicht, dass zuerst die Identität wechseln muss oder eine ausgesprochene Selbstbeschreibung eine Routine dauerhaft macht. Gewohnheitsforschung beschreibt ebenfalls ein Zusammenspiel von Verhalten und bewusst gewählten Zielen, statt nur einer Wirkungsrichtung. Für dieses breite Deutungsmodell ist der Befund gemischt. Es kann beim Ordnen einer Absicht helfen, aber ein konkreter Versuch liefert klarere Informationen als eine überzeugte Aussage über den Menschen, der du geworden sein sollst. Wenn die Beschreibung Druck macht, darfst du sie schlichter wählen.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Führe eine Notiz zum Lernen, nicht zum Retten einer Serie",idea:"Im Buch macht das Protokoll wiederholtes Verhalten sichtbar, aber eine Markierung im Kalender sollte eine nützliche Frage zu deinem Plan beantworten. Trenne Gelegenheit, Versuch und Ergebnis, wenn sie unterschiedlich sind, damit eine ungeöffnete Datei nicht dasselbe zählt wie ein fertiger Absatz. Frage nach einer ausgelassenen Gelegenheit, ob der Hinweis fehlte, der Schritt zu groß war oder eine andere Verantwortung Vorrang hatte. Wähle den nächsten machbaren Versuch und erlaube sichere Pausen, statt eine Strafe zu erfinden, um den Eindruck lückenloser Regelmäßigkeit zu bewahren; deine privaten Umstände musst du dafür niemandem offenlegen.",research:"Harkin und sein Team prüften 138 randomisierte Studien und fanden im Mittel bessere Zielerreichung durch Interventionen zur Fortschrittsbeobachtung. Größere Effekte gingen mit schriftlichem Festhalten oder Berichten einher, doch diese Vergleiche belegen weder eine Pflicht zum Teilen noch die Wirksamkeit jedes Formats. Die Übersicht bestätigt keine bestimmte Grenze für eine unterbrochene Serie; die unterschiedlichen Entstehungszeiten liefern sie ebenfalls nicht. Eine genaue private Notiz ist eine vernünftige Anpassung. Ihr Wert liegt in der Entscheidung, die du damit überprüfen kannst, statt eine lange Kette von Häkchen als Beweis für Gesundheit, Charakter oder künftigen Erfolg auszugeben. Geplante Arbeit und erledigte Arbeit bleiben verschiedene Angaben.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"Bereite in zwei Minuten einen wiederholbaren Einstieg vor",steps:["Wähle einen gewöhnlichen Hinweis für heute und eine nützliche Handlung, die in eine Minute passt.","Schreibe Hinweis und Handlung zusammen auf und lege das Material an den passenden Ort.","Lass den Plan sichtbar und halte eine Stelle für deine spätere Notiz zum Verlauf bereit."],decision:"Heute schreibe ich einen Hinweis und einen kleinen nützlichen Schritt auf und lege das Material bereit."},takeaway:"Behalte die wiederkehrende Situation und die ehrliche Notiz. Gehe mit Identitätssprache und der genauen Größe des Anfangs flexibler um, denn ihre stärksten Aussagen sind durch die geprüften Befunde nicht geklärt. Die Vorbereitung von zwei Minuten ist eine ODA-Anpassung, keine klinisch getestete Dosis und keine Garantie für Automatik. Du wählst einen Versuch für eine Gelegenheit. Danach kannst du prüfen, ob Hinweis, Handlung und Umstände gut genug zusammenpassen, um es erneut zu versuchen. Ändere den Plan, wenn er nicht mehr zum Alltag passt, statt passende Umstände nur zu behaupten."},it:{hook:"Un altro nuovo inizio durato tre giorni? Rendi più facile ripetere il prossimo tentativo.",intro:"Una routine convincente la domenica può diventare impraticabile il mercoledì. Clear invita a osservare le condizioni del comportamento, la grandezza del primo passo e il modo in cui ti descrivi. ODA verifica ogni idea separatamente: un consiglio utile e un meccanismo dimostrato non sono la stessa cosa. Puoi provare una proposta concreta senza accettarne tutte le promesse. Qui cerchiamo un’azione ripetibile nella tua giornata reale, un resoconto sincero di ciò che accade e la libertà di cambiare quando cambiano le condizioni. Non serve dichiarare una nuova personalità prima di vedere se il gesto trova posto nella tua vita.",ideas:[{id:"repeatable-context",title:"Dai all’azione un contesto che ritorna",idea:"Clear considera l’ambiente parte del lavoro necessario per cambiare, invece di affidare ogni ripetizione a una nuova fiammata di determinazione. Scegli una situazione abituale e rendi disponibile ciò che serve, senza aspettarti che una scrivania ben preparata risolva un carico eccessivo. Un adattamento ODA consiste nel lasciare aperto il documento per una sessione di scrittura prevista e decidere cosa farai quando ti siedi. Verifica che l’assetto funzioni anche con spostamenti, responsabilità di cura e strumenti di accessibilità; un orario ideale sulla carta non è automaticamente un’occasione disponibile nella giornata.",research:"La rassegna di Wood e Rünger riunisce diverse linee di ricerca sulla ripetizione in contesti ricorrenti come via verso comportamenti attivati da segnali. Una revisione del 2024, su 20 studi relativi ad abitudini di salute, ha trovato notevoli differenze nello sviluppo; soltanto quattro studi fornivano stime del tempo necessario. Non esiste una scadenza affidabile entro cui la tua azione debba diventare automatica, e queste ricerche non provano il tuo particolare assetto della scrivania. Usa il segnale per creare un’altra occasione possibile. Valuta le ripetizioni nel tempo, senza trasformare una mattina difficile in una conclusione sulla tua capacità di cambiare; neppure un obiettivo complesso diventa per questo interamente automatico.",verdict:"supported",sourceIds:["habit-context","habit-time"]},{id:"small-entry",title:"Riduci l’ingresso senza sostituire il lavoro",idea:"Il libro propone di abbassare la richiesta iniziale, così cominciare diventa una scelta concreta e non una trattativa sull’intero progetto. Aprire il file e scrivere la domanda da risolvere può essere un ingresso utile, purché resti collegato al lavoro desiderato senza prenderne stabilmente il posto. In una giornata piena, mantieni piccolo il primo passo e decidi separatamente se puoi continuare. Avere iniziato non ti obbliga a proseguire, e preparare il materiale non equivale a produrre un risultato; tieni distinta questa informazione anche quando valuti il tentativo.",research:"Le prove più solide vicine a questa proposta riguardano piani specifici e contesti ripetuti, non una dose universale di azioni minuscole. Gollwitzer e Sheeran hanno trovato benefici medi dei piani che collegano un segnale a una risposta in 94 verifiche, con ambienti e disegni di studio differenti. Ciò non dimostra che due minuti siano la soglia ottimale, che ogni piccola azione generi motivazione o che l’intero metodo del libro sia convalidato. Considera l’inizio breve un esperimento personale poco costoso. Registra se l’hai tentato, se è seguito lavoro utile e cosa cambieresti prima della prossima occasione, senza difendere una durata precisa come se fosse una legge.",verdict:"mixed",sourceIds:["if-then-plans","habit-context"]},{id:"identity-framing",title:"Lascia modificabile la descrizione di te",idea:"Clear collega le scelte ripetute alla percezione di chi siamo e suggerisce che una nuova descrizione personale possa sostenere una routine desiderata. Puoi usare l’idea con delicatezza, descrivendo il comportamento che stai praticando invece di annunciare un cambiamento completo della personalità. Se perdi un’occasione, rivedi il piano senza farne una prova di un’identità inferiore. Una descrizione utile rende più accessibile la scelta successiva; non chiede di negare incertezza, disabilità, impegni concorrenti o bisogno di sostegno, e non deve spiegare ogni aspetto della tua vita.",research:"Una meta-analisi del 2025 ha trovato piccoli miglioramenti dell’identità legata all’attività fisica dopo interventi su adulti. I programmi, però, combinavano ingredienti diversi e riguardavano l’esercizio: non dimostrano che l’identità debba cambiare prima né che dichiararne una nuova renda duratura una routine. La ricerca sulle abitudini descrive anche interazioni tra comportamento e obiettivi deliberati, non una sola direzione causale. Il giudizio su questa cornice generale è misto. Può aiutare a ordinare un’intenzione, ma il tentativo concreto dà informazioni più chiare di un’affermazione sicura sulla persona che saresti diventata. Se la definizione crea pressione, puoi renderla più semplice e vicina al gesto effettivo.",verdict:"mixed",sourceIds:["activity-identity","habit-context"]},{id:"honest-monitoring",title:"Tieni traccia per imparare, non per salvare una serie",idea:"Nel libro, il monitoraggio rende visibile la ripetizione, ma una spunta sul calendario dovrebbe rispondere a una domanda utile sul piano. Separa occasione, tentativo e risultato quando differiscono, così un file mai aperto non conta quanto un paragrafo finito. Dopo un’occasione persa, chiediti se mancava il segnale, se il passo era troppo grande o se un’altra responsabilità aveva priorità. Scegli il prossimo tentativo praticabile e permetti pause sicure, invece di inventare una punizione per difendere l’apparenza della costanza; non è necessario spiegare agli altri le tue circostanze private.",research:"Harkin e colleghi hanno esaminato 138 studi randomizzati e trovato che gli interventi di monitoraggio miglioravano mediamente il raggiungimento degli obiettivi. Gli effetti erano maggiori quando il progresso veniva registrato materialmente o comunicato, ma questi confronti non provano che condividere sia obbligatorio né che ogni formato funzioni. La revisione non convalida una specifica soglia di interruzione della serie, e la variabilità dei tempi di formazione non ne offre una. Una nota privata e precisa è un adattamento ragionevole. Il suo valore sta nella decisione che aiuta a rivedere, non nel presentare una lunga catena di spunte come prova di salute, carattere o successo futuro. Un’attività pianificata resta diversa da una attività svolta.",verdict:"supported",sourceIds:["progress-monitoring","habit-time"]}],action:{title:"Prepara un inizio ripetibile in due minuti",steps:["Scegli un segnale ordinario previsto oggi e un’azione utile che entri in un minuto.","Scrivi insieme segnale e azione, poi metti il materiale dove lo userai.","Lascia il piano visibile e uno spazio per annotare in seguito cosa è accaduto."],decision:"Oggi scriverò un segnale e un piccolo gesto utile, poi preparerò il materiale per provarlo."},takeaway:"Conserva il contesto ripetibile e il resoconto sincero. Usa con più flessibilità il linguaggio dell’identità e la dimensione precisa dell’inizio, perché le loro versioni più forti non sono risolte dalle prove considerate. La preparazione di due minuti è un adattamento ODA, non una dose clinica né una promessa di automatismo. Stai scegliendo un tentativo per un’occasione. Dopo potrai verificare se segnale, gesto e circostanze combaciano abbastanza da riprovare, senza difendere un piano che non corrisponde più alla tua giornata o ignorare le condizioni che lo hanno reso difficile."}}};export{e as default};
